/**
 * numberRingIndex.js — the exact index [PGL₂(O_k) : H] by coset enumeration, for H generated by
 * matrices over a number field k, using the presentation of PGL₂(O_k) from Voronoi's algorithm and
 * Brown's theorem (Arithmetic/Tools/numberRingGroups). This is the analogue over any totally real,
 * CM or cubic field of bianchi.js indexInBianchi, which knows only ℚ(√−1), ℚ(√−2), ℚ(√−3).
 *
 * Each matrix is first scaled into GL₂(O_k): its entries generate an ideal 𝔠 (the content); a
 * generator x of 𝔠 is an element of 𝔠 with |N(x)| = N(𝔠), found among the short vectors of 𝔠 for
 * the trace form Σ_σ |σ(x)|²; then M/x has coprime entries, and lies in GL₂(O_k) when its
 * determinant is a unit. Matrices that cannot be scaled (content not principal, or determinant not a
 * unit up to squares) are left out, so the subgroup enumerated may be smaller than H; the result says
 * how many were used. A matrix of GL₂(O_k) is written as a word by walking from a Voronoi cell to its
 * image (numberRingGroups brown.js wordFor), the word is multiplied out again and compared, and
 * Felsch's coset enumeration (felsch.js, table re-verified) gives the index.
 */
import { computeAll, supportCheck, freeReduce, invWord } from '../../Arithmetic/Tools/numberRingGroups/js/engine.js';
import { wordFor, evalWord } from '../../Arithmetic/Tools/numberRingGroups/js/brown.js';
import { NumberField } from '../../Arithmetic/Tools/numberRingGroups/js/nf.js';
import { RE, RI } from '../../Arithmetic/Tools/numberRingGroups/js/ring.js';
import { shortVectors } from '../../Arithmetic/Tools/numberRingGroups/js/lattice.js';
import { powerReduce } from './presentation.js';
import { enumerateFelsch, expressGenerators } from './felsch.js';
import { makeShortener } from './shortenWord.js';
import { hnf } from './intlin.js';

const cache = new Map();

/** Does the presentation engine handle the field of this polynomial (in w)? A cheap check. */
export function numberRingApplies(polySrc) {
    if (!polySrc) return false;
    try { return !supportCheck(new NumberField(String(polySrc))); } catch { return false; }
}

/**
 * The presentation of PGL₂(O_k): { R, nf, space, cx, P, GL, PGL, relators, orders, nGens, cells, ms } or
 * { error }. Computed afresh unless cache is set: a batch run (batch/pipeline.mjs) keeps one per field
 * in memory for the life of its worker, since it runs many groups over the same field; a single group
 * (the page, a test) does not rely on it.
 */
export function ringPresentation(polySrc, { seconds = 120, cache: useCache = false } = {}) {
    const key = String(polySrc).replace(/\s+/g, '');
    if (useCache && cache.has(key)) return cache.get(key);
    let out;
    try {
        const t0 = Date.now();
        const R = computeAll(key, { seconds, tietzeSeconds: 1e6, name: 'w' });          // the calculator's name for the root
        const { nf, space, cx, P, GL, PGL } = R._internal;
        const relators = PGL.relators.map((w) => w.map((x) => (x > 0 ? 2 * (x - 1) : 2 * (-x - 1) + 1)));
        const orders = new Map();
        for (const r of PGL.relators) if (r.length && r.every((x) => x === r[0])) orders.set(Math.abs(r[0]), r.length);
        out = { R, nf, space, cx, P, GL, PGL, relators, orders, nGens: PGL.gens.length, cells: cx.cells.length, ms: Date.now() - t0 };
    } catch (e) {
        out = { error: e.message || String(e) };
    }
    if (useCache) {
        cache.set(key, out);
        if (cache.size > 12) cache.delete(cache.keys().next().value);
    }
    return out;
}

// ------------------------------------------------------------------ matrices over k
/** an entry in ringEngine text (polynomial in w, rational coefficients) as a K element { v, d } */
function parseEntry(nf, src) {
    const ast = RE.parseExpr(String(src));
    const aCoords = RI.evalAst(ast, RI.fieldDomain(nf.field.K));
    const theta = RI.ratSolveRows(nf.subData.P, aCoords);
    return nf.fromPower(theta);
}
export const kMat = (nf) => ({
    mul: (A, B) => [0, 1].map((i) => [0, 1].map((j) => nf.kadd(nf.kmul(A[i][0], B[0][j]), nf.kmul(A[i][1], B[1][j])))),
    adj: (A) => [[A[1][1], neg(nf, A[0][1])], [neg(nf, A[1][0]), A[0][0]]],
});
const neg = (nf, a) => ({ v: nf.neg(a.v), d: a.d });

/** the matrices of words (letters ±(i+1)) in generators given by entries (ringEngine text), over K */
export function wordMatricesK(nf, genSrc, words) {
    const K = kMat(nf);
    const gens = genSrc.map((row) => {
        const e = row.map((s) => parseEntry(nf, s));
        return [[e[0], e[1]], [e[2], e[3]]];
    });
    const invs = gens.map((g) => K.adj(g));           // the adjugate: g⁻¹ up to the scalar det g
    const one = { v: nf.one(), d: 1n }, zero = { v: nf.zero(), d: 1n };
    return words.map((w) => {
        let M = [[one, zero], [zero, one]];
        for (const x of w) M = scaleDown(nf, K.mul(M, x > 0 ? gens[x - 1] : invs[-x - 1]));
        return M;
    });
}
// keep entries small: divide by the rational content (projectively harmless)
export function scaleDown(nf, M) {
    let g = 0n;
    const gcd = (a, b) => { a = a < 0n ? -a : a; b = b < 0n ? -b : b; while (b) [a, b] = [b, a % b]; return a; };
    let L = 1n;
    for (const row of M) for (const e of row) L = L / gcd(L, e.d) * e.d;
    const N = M.map((row) => row.map((e) => e.v.map((t) => t * (L / e.d))));
    for (const row of N) for (const e of row) for (const t of e) g = gcd(g, t);
    if (g === 0n) return M;
    return N.map((row) => row.map((e) => ({ v: e.map((t) => t / g), d: 1n })));
}

/** T2 Gram matrix of O in the integral basis: Σ over the embeddings of Re σ(ω_i) conj σ(ω_j) */
function t2Gram(nf) {
    if (nf._t2) return nf._t2;
    const n = nf.n, G = Array.from({ length: n }, () => new Array(n).fill(0));
    for (const w of nf.omegaAll) for (let i = 0; i < n; i++) for (let j = 0; j < n; j++) G[i][j] += w[i][0] * w[j][0] + w[i][1] * w[j][1];
    return (nf._t2 = G);
}

/** M (2×2 over K) scaled into GL₂(O), or null */
export function intoGL2O(nf, M) {
    // clear denominators
    const gcd = (a, b) => { a = a < 0n ? -a : a; b = b < 0n ? -b : b; while (b) [a, b] = [b, a % b]; return a; };
    let L = 1n;
    for (const row of M) for (const e of row) L = L / gcd(L, e.d) * e.d;
    let N = M.map((row) => row.map((e) => e.v.map((t) => t * (L / e.d))));
    const n = nf.n;
    // the content ideal as a lattice: the entries times the integral basis
    const gensC = [];
    for (const row of N) for (const e of row) if (!nf.isZero(e)) for (let j = 0; j < n; j++) gensC.push(nf.mul(e, nf.unit(j)));
    if (!gensC.length) return null;
    const H = hnf(gensC).H.slice(0, n);
    let idx = 1n;
    for (let i = 0; i < n; i++) idx *= H[i][i] < 0n ? -H[i][i] : H[i][i];
    if (idx === 0n) return null;
    if (idx !== 1n) {
        const x = idealGenerator(nf, H, idx);
        if (!x) return null;
        const xi = nf.inv(x);
        N = N.map((row) => row.map((e) => { const q = nf.kmul({ v: e, d: 1n }, xi); return q.d === 1n ? q.v : null; }));
        if (N.some((row) => row.some((e) => e === null))) return null;
    }
    const det = nf.sub(nf.mul(N[0][0], N[1][1]), nf.mul(N[0][1], N[1][0]));
    if (!nf.isUnit(det)) return null;
    return N;
}
/** an element of the ideal with rows H (ω-coordinates, HNF) whose norm is ±idx, or null */
function idealGenerator(nf, H, idx) {
    const n = nf.n, G0 = t2Gram(nf);
    const B = H.map((r) => r.map(Number));
    const G = Array.from({ length: n }, (_, i) => Array.from({ length: n }, (_, j) => { let s = 0; for (let a = 0; a < n; a++) for (let b = 0; b < n; b++) s += B[i][a] * G0[a][b] * B[j][b]; return s; }));
    let bound = 2 * n * Number(idx) ** (2 / n);
    for (let round = 0; round < 6; round++, bound *= 4) {
        let vs;
        try { vs = shortVectors(G, bound, { max: 20000 }); } catch { return null; }
        for (const y of vs) {
            const x = new Array(n).fill(0n);
            for (let i = 0; i < n; i++) if (y[i]) for (let j = 0; j < n; j++) x[j] += y[i] * H[i][j];
            const N = nf.norm(x);
            if (N === idx || N === -idx) return x;
        }
    }
    return null;
}

// ------------------------------------------------------------------ conjugating a bounded group into GL₂(O_k)
/**
 * For matrices generating a group H ⊂ PGL₂(k) that is bounded at every prime: the matrices of a
 * finite-index subgroup H⁺ (all of H unless some generator inverts an edge of a tree), conjugated by
 * one g ∈ GL₂(k) into GL₂(O_k). Steps: (1) the primes dividing the determinants and denominators;
 * (2) at a prime where some determinant has odd valuation, H⁺ = the kernel of the parities (Schreier
 * generators), which fixes a vertex there; (3) each determinant made a unit by the generators of the
 * prime ideals; (4) a lattice L ⊂ k² stable under H⁺ (the O-span of the orbit of O², by saturation);
 * (5) an O-basis of L, which is free when the ideals met are principal; g = that basis. Returns
 * { mats (GL₂(O)), g, evenIndex } or null (an ideal without a generator found, or no stable lattice).
 */
export function conjugateIntoGL2O(nf, mats, { maxGens = 1500, maxRounds = 80, words = null } = {}) {
    const n = nf.n, O = nf.subData.O, K = kMat(nf);
    const Q = (x) => new RI.Rat(x);
    const kInv = (a) => { const i = nf.inv(a.v); return { v: nf.scale(i.v, a.d), d: i.d }; };
    const det = (M) => nf.ksub(nf.kmul(M[0][0], M[1][1]), nf.kmul(M[0][1], M[1][0]));
    const kScale = (M, c) => M.map((row) => row.map((e) => nf.kmul(e, c)));
    // (1) the bad rational primes
    const ps = new Set();
    const addPrimes = (x) => { if (x < 0n) x = -x; if (x > 1n) { const f = RI.factorInt(x); if (!f.complete) throw new Error('factorization'); for (const [p] of f.factors) ps.add(p); } };
    for (const M of mats) {
        for (const row of M) for (const e of row) addPrimes(e.d);
        const d = det(M);
        if (nf.isZero(d.v)) return null;
        addPrimes(nf.norm(d.v)); addPrimes(d.d);
    }
    const primes = [...ps].flatMap((p) => RI.primesAbove(O, p));
    const val = (pr, a) => RI.valuationSV(O, pr, { v: a.v, den: a.d });
    // (2) parities of the determinants; the even subgroup by Schreier generators
    const par = mats.map((M) => { const d = det(M); return primes.map((pr) => ((val(pr, d) % 2) + 2) % 2); });
    // words of the matrices in the caller's generators (letters ±(i+1)), carried along
    const W0 = words || mats.map((_, i) => [i + 1]);
    const invW = (w) => w.slice().reverse().map((x) => -x);
    const freeRedW = (w) => { const o = []; for (const x of w) { if (o.length && o[o.length - 1] === -x) o.pop(); else o.push(x); } return o; };
    let gens = mats, gensW = W0, evenIndex = 1, repList = null;
    if (par.some((v) => v.some((b) => b))) {
        const key = (v) => v.join('');
        const add = (u, v) => u.map((x, i) => x ^ v[i]);
        const zero = primes.map(() => 0);
        const reps = new Map([[key(zero), { v: zero, t: [[{ v: nf.one(), d: 1n }, { v: nf.zero(), d: 1n }], [{ v: nf.zero(), d: 1n }, { v: nf.one(), d: 1n }]], w: [] }]]);
        const queue = [zero];
        while (queue.length) {
            const c = queue.shift();
            mats.forEach((M, i) => { const c2 = add(c, par[i]); if (!reps.has(key(c2))) { const r0 = reps.get(key(c)); reps.set(key(c2), { v: c2, t: K.mul(r0.t, M), w: r0.w.concat(W0[i]) }); queue.push(c2); } });
        }
        evenIndex = reps.size;
        repList = [...reps.values()];
        gens = []; gensW = [];
        for (const { v, t, w } of reps.values()) mats.forEach((M, i) => {
            if (gens.length >= maxGens) return;
            const U = reps.get(key(add(v, par[i])));
            // t·M·u⁻¹, with u⁻¹ = adj(u)/det(u) (projectively: adj(u))
            gens.push(scaleDown(nf, K.mul(K.mul(t, M), K.adj(U.t))));
            gensW.push(freeRedW(w.concat(W0[i], invW(U.w))));
        });
    }
    // (3) unit determinants: divide by ∏ π^{v/2}
    const piOf = new Map();
    const pi = (pr) => {
        if (!piOf.has(pr)) {
            const x = idealGenerator(nf, pr.H, pr.p ** BigInt(pr.f));
            piOf.set(pr, x);
        }
        return piOf.get(pr);
    };
    const normed = [];
    for (const M of gens) {
        const d = det(M);
        let lam = { v: nf.one(), d: 1n };
        for (const pr of primes) {
            const v = val(pr, d);
            if (v % 2) return null;
            if (!v) continue;
            const x = pi(pr);
            if (!x) return null;
            const h = v / 2, xx = h > 0 ? kInv({ v: x, d: 1n }) : { v: x, d: 1n };
            for (let t = 0; t < Math.abs(h); t++) lam = nf.kmul(lam, xx);
        }
        const M2 = kScale(M, lam);
        if (!nf.isUnit(det(M2).v) || det(M2).d !== 1n) return null;
        normed.push(M2);
    }
    // (4) a stable lattice: L ← L + Σ A·L over A = M, M⁻¹
    const acts = normed.flatMap((M) => [M, kScale(K.adj(M), kInv(det(M)))]);
    const coords = (x, y) => x.v.map((t) => new RI.Rat(t, x.d)).concat(y.v.map((t) => new RI.Rat(t, y.d)));
    const toVec = (row, den) => [{ v: row.slice(0, n), d: den }, { v: row.slice(n), d: den }].map((a) => { let g = a.d; for (const t of a.v) { const b = t < 0n ? -t : t; let x = g, y = b; while (y) [x, y] = [y, x % y]; g = x; } return g > 1n ? { v: a.v.map((t) => t / g), d: a.d / g } : a; });
    let Lat = RI.ratLattice(Array.from({ length: 2 * n }, (_, i) => Array.from({ length: 2 * n }, (_, j) => Q(i === j ? 1n : 0n))), 2 * n);
    const same = (A, B) => A.den === B.den && A.H.length === B.H.length && A.H.every((r, i) => r.every((x, j) => x === B.H[i][j]));
    let stable = false;
    for (let round = 0; round < maxRounds; round++) {
        const basis = Lat.H.map((r) => toVec(r, Lat.den));
        const vecs = basis.map(([x, y]) => coords(x, y));
        for (const A of acts) for (const [x, y] of basis) {
            const u = nf.kadd(nf.kmul(A[0][0], x), nf.kmul(A[0][1], y)), w = nf.kadd(nf.kmul(A[1][0], x), nf.kmul(A[1][1], y));
            vecs.push(coords(u, w));
        }
        const L2 = RI.ratLattice(vecs, 2 * n);
        if (same(L2, Lat)) { stable = true; break; }
        Lat = L2;
    }
    if (!stable) return null;
    // (5) an O-basis: γ·e₁ spanning L ∩ (k × 0), and (x, β) with β generating the projection to the second coordinate
    const rows = Lat.H.map((r) => r.slice(n).concat(r.slice(0, n)));       // second block first
    const Hs = RI.hnf(rows, 2 * n);
    if (Hs.length !== 2 * n) return null;
    const Bproj = Hs.slice(0, n).map((r) => r.slice(0, n)), Bker = Hs.slice(n).map((r) => r.slice(n));
    const detI = (H) => H.reduce((acc, r, i) => acc * (r[i] < 0n ? -r[i] : r[i]), 1n);
    const gen = (H) => { const N = detI(H); return N === 1n ? nf.one() : idealGenerator(nf, H, N); };
    const bP = gen(Bproj), cK = gen(Bker);
    if (!bP || !cK) return null;
    // (x', β') in den·L with β' = bP: solve bP = Σ c_i Bproj[i] (echelon)
    const c = new Array(n).fill(0n), rest = bP.slice();
    for (let i = 0; i < n; i++) {
        const col = Bproj[i].findIndex((t) => t !== 0n);
        if (rest[col] % Bproj[i][col] !== 0n) return null;
        c[i] = rest[col] / Bproj[i][col];
        if (c[i]) for (let j = 0; j < n; j++) rest[j] -= c[i] * Bproj[i][j];
    }
    if (rest.some((t) => t !== 0n)) return null;
    const xp = new Array(n).fill(0n);
    for (let i = 0; i < n; i++) if (c[i]) for (let j = 0; j < n; j++) xp[j] += c[i] * Hs[i][n + j];
    const den = Lat.den;
    const g = [[{ v: cK, d: den }, { v: xp, d: den }], [{ v: nf.zero(), d: 1n }, { v: bP, d: den }]].map((row) => row.map((a) => (nf.isZero(a.v) ? { v: a.v, d: 1n } : a)));
    const gInv = kScale(K.adj(g), kInv(det(g)));
    const out = [];
    for (const M of normed) {
        const C = K.mul(K.mul(gInv, M), g);
        if (C.some((row) => row.some((e) => !nf.isZero(e.v) && e.d !== 1n))) return null;
        const Ci = C.map((row) => row.map((e) => e.v));
        if (!nf.isUnit(nf.sub(nf.mul(Ci[0][0], Ci[1][1]), nf.mul(Ci[0][1], Ci[1][0])))) return null;
        out.push(Ci);
    }
    // is g itself in GL₂(O)·k^× (so the conjugate of PGL₂(O) is PGL₂(O))?
    const trivial = !!intoGL2O(nf, g);
    // for P. Hall's extension (numberRingPresentation.js): the coset representatives { v, t, w } of the
    // even subgroup (v its parity class, t a matrix of H, w its word), and the parity of any matrix
    const parity = (M) => { const d = det(M); return primes.map((pr) => ((val(pr, d) % 2) + 2) % 2); };
    return { mats: out, words: gensW, g, evenIndex, trivial, reps: repList, parity };
}

// ------------------------------------------------------------------ the index
/**
 * [PGL₂(O_k) : H] for H generated by the matrices of words in generators given by entries.
 * Returns { index, used, skipped, ms, limit, error, cells }. index is the index of the subgroup
 * generated by the `used` matrices (all of H when skipped = 0).
 */
export function indexInPGL2O(polySrc, genSrc, words, opts = {}) {
    const L = opts.presentation || ringPresentation(polySrc, { seconds: opts.presentationSeconds ?? 120, cache: !!opts.cache });
    if (L.error) return { index: null, error: `presentation: ${L.error}` };
    let mats, userGens;
    try {
        mats = wordMatricesK(L.nf, genSrc, words);
        userGens = wordMatricesK(L.nf, genSrc, genSrc.map((_, i) => [i + 1]));
    } catch (e) { return { index: null, error: `reading the matrices: ${e.message}` }; }
    return indexOfMatrices(polySrc, mats, { ...opts, presentation: L, matWords: words, userGens });
}

/**
 * [PGL₂(O_k) : ⟨mats⟩] for 2×2 matrices over K (entries { v, d } in the integral basis). opts.presentation:
 * a presentation already built (ringPresentation); opts.cache: use the per-field cache (batch runs).
 */
export function indexOfMatrices(polySrc, mats, { seconds = 10, maxCosets = 1500000, presentationSeconds = 120, maxWalk = 60000, wordSeconds = null, conjugate = true, presentation = null, cache: useCache = false, matWords = null, userGens = null, express = false } = {}) {
    const t0 = Date.now();
    const L = presentation || ringPresentation(polySrc, { seconds: presentationSeconds, cache: useCache });
    if (L.error) return { index: null, error: `presentation: ${L.error}` };
    const { nf, space, cx, P, GL, PGL, relators, orders, nGens } = L;
    let seed = 2024;
    const rng = () => { seed = (seed * 1103515245 + 12345) % 2147483648; return seed / 2147483648; };
    const subst = (w, express) => freeReduce([].concat(...w.map((x) => (x > 0 ? express(x) : invWord(express(-x))))));
    const subWords = [], seen = new Set();
    let skipped = 0;
    const wordDeadline = Date.now() + 1000 * (wordSeconds ?? Math.max(5, seconds));
    // one conjugation for the whole group when it is bounded everywhere; else each matrix on its own
    let conj = null;
    const direct = mats.map((M) => intoGL2O(nf, M));
    if (conjugate && direct.some((g) => !g)) { try { conj = conjugateIntoGL2O(nf, mats, { words: matWords }); } catch { conj = null; } }
    const MW = matWords || mats.map((_, i) => [i + 1]);
    if (conj && !conj.words) conj.words = MW;
    const list = conj ? conj.mats.map((m, i) => ({ ok: m, w: conj.words[i] })) : direct.map((g, i) => (g ? { ok: g, w: MW[i] } : { M: mats[i], w: MW[i] }));
    const subUser = [];                                  // each subgroup generator's word in the caller's generators
    for (const item of list) {
        if (Date.now() > wordDeadline) { skipped++; continue; }
        const g = item.ok || intoGL2O(nf, item.M);
        if (!g) { skipped++; continue; }
        let raw;
        try { raw = wordFor(cx, P, g, { rng, maxSteps: maxWalk }); } catch { skipped++; continue; }
        const w = powerReduce(subst(subst(raw, GL.express), PGL.express), orders, false);
        // check: the word is g in PGL₂ (up to a scalar)
        const h = space.matMul(evalWord(space, PGL.gens, w), space.matInv(g));
        if (!(nf.isZero(h[0][1]) && nf.isZero(h[1][0]) && nf.eq(h[0][0], h[1][1]))) throw new Error('internal: a subgroup word does not evaluate to its matrix');
        const key = w.join(',');
        if (seen.has(key)) continue;
        seen.add(key);
        subWords.push(w.map((x) => (x > 0 ? 2 * (x - 1) : 2 * (-x - 1) + 1)));
        subUser.push(item.w);
    }
    const used = list.length - skipped;
    if (!used) return { index: null, used, skipped, error: 'no matrix lies in PGL₂(O_k)', ms: Date.now() - t0, cells: L.cells };
    const tTC = Date.now();
    const tc = enumerateFelsch(nGens, relators, subWords, { maxCosets, seconds });
    const tcMs = Date.now() - tTC;
    const out = { index: tc.index ?? null, limit: tc.limit ?? null, used, skipped, conjugated: !!conj && !conj.trivial, evenIndex: conj ? conj.evenIndex : 1, defined: tc.defined, ms: Date.now() - t0, tcMs, cells: L.cells, presentationMs: L.ms, gens: nGens, relators: relators.length };
    if (express && out.index === 1 && userGens) {
        try { out.express = expressPGL2O(L, subWords, subUser, userGens, conj, { seconds: Math.max(5, seconds) }); }
        catch (e) { out.express = { error: e.message }; }
    }
    return out;
}

/**
 * When the subgroup is all of PGL₂(O_k) (index 1): the generators p_1 … p_m of its presentation in
 * terms of the caller's generators, by augmented coset enumeration (felsch.js), then the subgroup
 * generators' words in the caller's generators, and a shortening checked in PGL₂(k). After a
 * conjugation by g into PGL₂(O_k), the words are for g·p·g⁻¹. Returns { letters: [{ matrix (TeX),
 * word }], conjugator (TeX or null), ms }.
 */
function expressPGL2O(L, subWords, subUser, userGens, conj, { seconds = 5, maxLength = 200000 } = {}) {
    const t0 = Date.now();
    const { nf, PGL, relators, nGens } = L;
    const E = expressGenerators(nGens, relators, subWords, { seconds, maxLength });
    if (E.index !== 1) throw new Error(E.limit ? `augmented enumeration: ${E.limit}` : `index ${E.index}`);
    const K = kMat(nf);
    const kInv = (a) => { const i = nf.inv(a.v); return { v: nf.scale(i.v, a.d), d: i.d }; };
    // matrices up to scalars: divide by the first nonzero entry
    const normal = (M) => {
        const flat = [M[0][0], M[0][1], M[1][0], M[1][1]];
        const f = flat.find((e) => !nf.isZero(e.v));
        const fi = kInv(f);
        const n2 = flat.map((e) => nf.kmul(e, fi));
        return [[n2[0], n2[1]], [n2[2], n2[3]]];
    };
    const ops = {
        mul: (X, Y) => normal(K.mul(X, Y)), inv: (X) => normal(K.adj(X)),
        one: [[{ v: nf.one(), d: 1n }, { v: nf.zero(), d: 1n }], [{ v: nf.zero(), d: 1n }, { v: nf.one(), d: 1n }]],
        key: (X) => normal(X).flat().map((e) => `${e.v.join(',')}/${e.d}`).join(';'),
    };
    const gensN = userGens.map(normal);
    const shortener = makeShortener(gensN, ops, { maxElements: 8000, seconds: 0.5 });
    const inverse = (w) => w.slice().reverse().map((x) => -x);
    const freeRed = (w) => { const o = []; for (const x of w) { if (o.length && o[o.length - 1] === -x) o.pop(); else o.push(x); } return o; };
    const evalUser = (w) => w.reduce((X, x) => ops.mul(X, x > 0 ? gensN[x - 1] : ops.inv(gensN[-x - 1])), ops.one);
    const g = conj && !conj.trivial ? conj.g : null;
    const gi = g ? K.adj(g) : null;
    const letters = E.words.map((w, k) => {
        const P = PGL.gens[k].mat.map((row) => row.map((x) => ({ v: x, d: 1n })));
        const target = g ? K.mul(K.mul(g, P), gi) : P;
        const tex = `\\begin{pmatrix} ${nf.tex(PGL.gens[k].mat[0][0])} & ${nf.tex(PGL.gens[k].mat[0][1])} \\\\ ${nf.tex(PGL.gens[k].mat[1][0])} & ${nf.tex(PGL.gens[k].mat[1][1])} \\end{pmatrix}`;
        if (!w) return { matrix: tex, word: null };
        let u = freeRed([].concat(...w.map((x) => (x > 0 ? subUser[x - 1] : inverse(subUser[-x - 1])))));
        u = shortener.shorten(u, { seconds: 0.5 });
        if (ops.key(evalUser(u)) !== ops.key(target)) throw new Error('internal: an expressed generator does not evaluate to it');
        return { matrix: tex, word: u };
    });
    return { letters, conjugator: g ? g.map((row) => row.map((e) => nf.tex(e))) : null, nodes: E.nodes, ms: Date.now() - t0 };
}
